import{_ as p,c as e,o as t,af as r}from"./chunks/framework.4G89wRmb.js";const h=JSON.parse('{"title":"5.9 后记","description":"","frontmatter":{"title":"5.9 后记"},"headers":[],"relativePath":"archives_n_arts/arts/nambu_blue/5.9.md","filePath":"archives_n_arts/arts/nambu_blue/5.9.md"}'),_={name:"archives_n_arts/arts/nambu_blue/5.9.md"};function s(n,a,i,o,l,c){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="五" tabindex="-1">五 <a class="header-anchor" href="#五" aria-label="Permalink to “五”">​</a></h1><h2 id="_9-后记" tabindex="-1">9. 后记 <a class="header-anchor" href="#_9-后记" aria-label="Permalink to “9. 后记”">​</a></h2><p>《南武蓝》这本书，我把它当作一部记录百年名校“以文化人”的纪实报告来写。</p><p>它是一本记录南武一段发展历程的史料留存，更像是我2011年来当校长到2023年退休，这12年在南武进行教育教学改革探索的纸质版的经历。</p><p>《劝学》中写到，“青，取之于蓝，而青于蓝”；“蓝”，是一种有境界、有品质的教育文化；蓝，代表海洋、天空，象征深邃、辽阔、幽静。书名为《南武 蓝》，其中的“蓝”，代表南武独特的文化，是南武“用文化滋养有灵魂的教育”的底色。</p><p>写此书除了保存历史外，更有向南武百年历史致敬之意，谨以此书向南武建校120周年献礼！</p><p>特别感谢顾明远先生为本书题写书名。先生一直关心南武文化建设，多次为南武集团学校题写校名，2015年1月先生还曾为《南武往事》题写序文，叮嘱我们：“南武中学发展的历史，是一笔无法估量的宝贵财富，是新时期的南武中学发展的基础。”</p><p>铭记先生的教导，全书从“文化密码”“文化滋润”“文化融创”“文化感悟”四个方面来讲述南武的教育故事，传承、弘扬南武文化。</p><p>文化是南武办学的独特资源，打好文化牌是当好南武校长的首要功力，成为文化名校是南武发展的伟大战略。学校文化建设最重要的是要把学校的文化当作一种促进学校发展的“力”，文化助力，文化发力，文化聚力。作为一个建校120年历史文化名校，一定有它的文化根基，有它自己的文化密码。密码在哪里呢？在“南武，就是广州城最早的称呼”的典故里，在“百年南武，弦歌不辍”“古风南武，韵味绵长”的历程和故事里，在“无体育，不南武”“北有南开，南有南武”“坚忍奉公，力学爱国”磨砺出的南武精神内涵里，更是在“市实时期”创造新时代南武新丰碑里，在“拓潜教育”凝练的南武教育思想里。</p><p>如何传承学校历史文化，用好学校文化资源，和社会优秀文化、时代先进文化一起“以文化人”，促进学校内涵发展？这是本书的核心部分，我们选择的是“文化滋润”和“文化融创”。</p><p>很早我们就提出学校德育“不能根据5%的困难、偏常、问题学生，来制定95%优秀学生的教育政策和教育活动安排”，学校德育要实现从“管人”到“育人”转轨。这就需要我们有新的育人理念和方式——“文化滋润”。厚植“南武人，爱南武，为南武”的南武情怀，用南武“大爱”铸就“南武大先生”，让爱相伴，在追光的路上照亮别人、闪亮自己。探索“善、思、雅、新”做文雅的南武人系列教育活动，创建“古风·蓝韵”拓潜南武教育特色，设立“达微杯”“级管会”等南武新质文化创新共生场，以尊重、信任、育人为本的理念为学生搭建“自管自育”成长平台，设立“南华奖”这样让南武学子记住一辈子的奖励标杆，把“没有爱就没有教育，没有兴趣就没有学习，教书育人在细微处，学生成长在活动中”落实在教书育人的过程中，培根铸魂，启智润心。</p><p>传承学校文化的落脚点和归宿在于文化创新。但创新的土壤一定是自身的文化基础。有人说学校就像是一个“泡菜坛子”，有什么水汁，出品什么泡菜。我认为学校就是一个文化生成场，一个学习共生场域，历史和未来在这里拥抱，国内外教育思想在这里交融。曾听一个名校长讲过，一个优秀的校长，一定是一个会利用资源的校长。我个人也深深地觉得，资源的利用对一个学校的发展、对学生成长实在太重要了。我越来越觉得，办学校就是在一个融创场，课程的融创、课堂教学的融创、学习方式的融创、人才培养的融创等，归根到底就是文化的融创。“融”是一个很有教育韵味的字，融融、融合、融汇、融化、融创、融通等。“融”是教育发展的一种趋势，所有的成长都是“融”的结果。融合古今中外，我们坚持了12年的“思维教学”变革实践，延续“市实时期”“拓潜教育”的探索精神。2012年开设“CCAE班”，尝试中美教育融合，互鉴共享，追逐“携手同登世界之舞台，增我南武之璀璨”南武百年梦想。“你不一定出国，但你必须具备国际视野”，南武对国际理解教育的“融化”有自己独特的探索。助力思维，赋能教学建设，信息技术与教学的深度融合，把南武科学、智慧教育跟南武的“思维教学”紧密联通，因为科学的学习更注重过程，更注重实践，更注重学生的逻辑思维、科学思维。建设南武教育集团，最初就是“融”字当头，把“文化凝聚，品牌作育，优质共同途”作为基本思路，文化聚力，擦亮“百年南武”教育品牌。</p><p>“推石爬坡”“小大之辩”，著名的文化典故，也是我当12年南武校长最深的文化感悟。西西弗斯推石爬坡的神话看起来好像是上帝对他的惩罚，但我却觉得这是西西弗斯伟大精神、顽强意志的生动展示。正是南武百年历史深厚的文化底蕴、坚奉力爱的校训精神，支柱我们筚路蓝缕、推石爬坡。</p><p>“小大之辩”本来是庄子哲学的一个命题，引用来喻释“办教育如烹小鲜”，也抚慰自己虽“小”，也有“大”的作为，做好南武自己的事。南武的确有“小”，但不能因“小”而躺平，也不能因“大”而茫然。南武的“小大之辩”就是从“小”处入手，从“小”处找功力，从“小”处显品质，抓好“细小”，做好“大”文章，在“大”上下力气。归根结底，南武的“小大之辩”就是一切从南武的实际出发，尊重学校实际，尊重学生发展规律，真心办教育，办“适性的教育”，真实的教育。</p><p>“致中和，天地位焉，万物育焉。”各守其分，适应处境，合规律成长；办教育像农耕，精耕细作，悉心呵护，各得其所，循序渐进，厚积薄发，行稳致高，独行疾，位育远，推石爬坡，保持进步。争取优秀，坚守品质。</p><p>文化这玩意儿很多人说说不清，但我力求用这本书说清！</p><p>谨以此书献给建校120周年的南武，感谢百年南武知遇之恩，感谢百年南武文化对我教育品质的滋养浸润！感谢十几年来和我一道推石爬坡的全体师生和员工，是你们给了我前进的动力、坚持的力量、拼搏的勇气！</p><p>南武人，爱南武，为南武！</p><p>陈祥春</p><p>2024年10月15日</p>',20)])])}const m=p(_,[["render",s]]);export{h as __pageData,m as default};
